pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 mtFeeRate) public {
        vm.assume(mtFeeRate <= 10**18);
        vm.prank(address(0x1));
        // The reference contract requires that after calling adjustMtFeeRate,
        // if the RState is BELOW_ONE and base reserve is below target,
        // then _BASE_TARGET_ must equal _BASE_RESERVE_.
        // The bugged version fails to update _BASE_TARGET_ in that branch.
        c.adjustMtFeeRate(mtFeeRate);
        (uint256 i, uint256 K, uint256 B, uint256 Q, uint256 B0, uint256 Q0, uint256 R) = c.getPMMStateForCall();
        if (R == uint256(2) && B < B0) {
            assertTrue(B0 == B);
        } else {
            assertTrue(true);
        }
    }
}

