pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 mtFeeRate) public {
        // 1. Assume admissible mtFeeRate
        vm.assume(mtFeeRate <= 10**18);
        // 2. Drive through adjustMtFeeRate
        // We need to be the maintainer, which is currently address(this) because we deployed
        bool ok;
        try c.adjustMtFeeRate(mtFeeRate) { ok = true; } catch { ok = false; }
        if (!ok) return; // Revert is also acceptable, invariant only needed on success
        // 3. Assert: after any successful adjustMtFeeRate, _BASE_TARGET_ equals _BASE_RESERVE_ if R is ONE
        // Since adjustMtFeeRate does not change reserves or targets, the corrected state may be ONE
        // We check that if R is ONE, _BASE_TARGET_ == _BASE_RESERVE_
        ( , , , , uint256 B0, , uint256 R) = c.getPMMStateForCall();
        // The reference ensures B0 == B when R == ONE, the mutant sets B0 to 0 breaking this
        uint112 baseReserve = c._BASE_RESERVE_();
        if (R == uint256(1)) {
            assertTrue(B0 == baseReserve);
        }
    }
}

